<script setup lang="ts">definePageMeta({layout:false});const {data}=await useFetch('/api/auth/setup-status');if(!data.value?.required)await navigateTo('/admin/login');const form=reactive({username:'admin',email:'',password:'',siteName:'Northstar'});const error=ref('');async function submit(){try{await $fetch('/api/auth/setup',{method:'POST',body:form});await navigateTo('/admin')}catch(e){error.value=(e as {data?:{message?:string}}).data?.message||'初始化失败'}}</script>
<template><main class="min-h-screen grid place-items-center p-5"><form class="w-full max-w-md rounded-2xl border p-8" style="border-color:var(--border);background:var(--surface)" @submit.prevent="submit"><p class="text-xs uppercase tracking-widest" style="color:var(--accent)">First run</p><h1 class="mt-2 text-3xl font-semibold">初始化你的博客</h1><p class="mt-2 text-sm" style="color:var(--muted)">此步骤只能完成一次。</p><div class="mt-8 grid gap-4"><label>站点名称<input v-model="form.siteName" required class="mt-1 w-full rounded-lg border bg-transparent p-3"></label><label>用户名<input v-model="form.username" required class="mt-1 w-full rounded-lg border bg-transparent p-3"></label><label>Email<input v-model="form.email" required type="email" class="mt-1 w-full rounded-lg border bg-transparent p-3"></label><label>密码（至少 12 位）<input v-model="form.password" required minlength="12" type="password" class="mt-1 w-full rounded-lg border bg-transparent p-3"></label></div><p v-if="error" class="mt-4 text-red-600">{{error}}</p><button class="mt-6 w-full rounded-lg py-3 text-white" style="background:var(--accent)">完成初始化</button></form></main></template>
